INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_BAS_ABRASAX_IRENAE','ENT_BAS_ABRASAX','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','Irenaeus, Against Heresies','They hold that their chief is Abraxas; and, on this account, that word contains in itself the numbers amounting to three hundred and sixty-five. Chapter XXV [ edit ] Doctrines of Carpocrates. 1 . Carpocrates, again, and his followers maintain that the world and the things which are therein were created by angels greatly inferior to the unbegotten Father.','Roberts & Rambaut (Ante-Nicene Fathers)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS',NULL,'heresiological-verbatim',NULL,true,'Heresiological source (hostile witness) located by name; verify chapter.section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_VAL_AEINOUS_IRENAE','ENT_VAL_AEINOUS','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','Irenaeus, Against Heresies','give the following names: Paracletus and Pistis, Patricos and Elpis, Metricos and Agape, Ainos and Synesis, Ecclesiasticus and Macariotes, Theletos and Sophia. 3 . Such are the thirty Aeons in the erroneous system of these men; and they are described as being wrapped up, so to speak, in silence, and known to none [except these professing teachers].','Roberts & Rambaut (Ante-Nicene Fathers)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS',NULL,'heresiological-verbatim',NULL,true,'Heresiological source (hostile witness) located by name; verify chapter.section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_VAL_AKINETOS_IRENAE','ENT_VAL_AKINETOS','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','Irenaeus, Against Heresies','Logos and Zoe, after producing Anthropos and Ecclesia, sent forth other ten Aeons, whose names are the following: Bythius and Mixis, Ageratos and Henosis, Autophyes and Hedone, Acinetos and Syncrasis, Monogenes and Macaria. These are the ten Aeons whom they declare to have been produced by Logos and Zoe.','Roberts & Rambaut (Ante-Nicene Fathers)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS',NULL,'heresiological-verbatim',NULL,true,'Heresiological source (hostile witness) located by name; verify chapter.section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_VAL_APOLYTROSIS_IRENAE','ENT_VAL_APOLYTROSIS','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','Irenaeus, Against Heresies','But even if he should happen to lay hold upon them, then they might simply repeat these words, while standing in his presence along with the "Redemption:" "O thou, who sittest beside God, and the mystical, eternal Sige, thou through whom the angels (mightiness), who continually behold the face of the Father, having thee as their guide and introducer, do derive their forms from above, which she in the greatness of her daring inspiring with mind on account o','Roberts & Rambaut (Ante-Nicene Fathers)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS',NULL,'heresiological-verbatim',NULL,true,'Heresiological source (hostile witness) located by name; verify chapter.section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_VAL_BYTHIOS_IRENAE','ENT_VAL_BYTHIOS','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','Irenaeus, Against Heresies','Logos and Zoe, after producing Anthropos and Ecclesia, sent forth other ten Aeons, whose names are the following: Bythius and Mixis, Ageratos and Henosis, Autophyes and Hedone, Acinetos and Syncrasis, Monogenes and Macaria. These are the ten Aeons whom they declare to have been produced by Logos and Zoe.','Roberts & Rambaut (Ante-Nicene Fathers)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS',NULL,'heresiological-verbatim',NULL,true,'Heresiological source (hostile witness) located by name; verify chapter.section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_VAL_EKKLESIASTIKOS_IRENAE','ENT_VAL_EKKLESIASTIKOS','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','Irenaeus, Against Heresies','Elpis, Hope ; Metricos, Metrical ; Agape, Love ; Ainos, Praise ; Synesis, Understanding ; Ecclesiasticus, Ecclesiastical ; Macariotes, Felicity ; Theletos, Desiderated ; Sophia, Wisdom . ↑ Some omit εν πληθει , while others render the words "a definite number," thus: "And if there is anything else in Scripture which is referred to by a definite number." ↑ Alluding to the Gnostic notion that, in generation, the male gives form, the female substance.','Roberts & Rambaut (Ante-Nicene Fathers)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS',NULL,'heresiological-verbatim',NULL,true,'Heresiological source (hostile witness) located by name; verify chapter.section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_VAL_MAKARIOTES_IRENAE','ENT_VAL_MAKARIOTES','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','Irenaeus, Against Heresies','; Agape, Love ; Ainos, Praise ; Synesis, Understanding ; Ecclesiasticus, Ecclesiastical ; Macariotes, Felicity ; Theletos, Desiderated ; Sophia, Wisdom . ↑ Some omit εν πληθει , while others render the words "a definite number," thus: "And if there is anything else in Scripture which is referred to by a definite number." ↑ Alluding to the Gnostic notion that, in generation, the male gives form, the female substance.','Roberts & Rambaut (Ante-Nicene Fathers)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS',NULL,'heresiological-verbatim',NULL,true,'Heresiological source (hostile witness) located by name; verify chapter.section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_VAL_METRIKOS_IRENAE','ENT_VAL_METRIKOS','SRC_IRENAEUS_AH','Irenaeus, Against Heresies','Irenaeus, Against Heresies','They then add that Anthropos himself, along with Ecclesia, produced twelve Aeons, to whom they give the following names: Paracletus and Pistis, Patricos and Elpis, Metricos and Agape, Ainos and Synesis, Ecclesiasticus and Macariotes, Theletos and Sophia. 3 . Such are the thirty Aeons in the erroneous system of these men; and they are described as being wrapped up, so to speak, in silence, and known to none [except these professing teachers].','Roberts & Rambaut (Ante-Nicene Fathers)',1885,'https://en.wikisource.org/wiki/Ante-Nicene_Fathers/Volume_I/IRENAEUS',NULL,'heresiological-verbatim',NULL,true,'Heresiological source (hostile witness) located by name; verify chapter.section.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
